// Standalone Base64 Portrait Fallback & Smart Asset Loader for Bui Phi Long Portfolio
window.__PORTRAIT_FALLBACK = "data:image/jpeg;base64,";
document.querySelectorAll('#hero-exec-portrait, #lightbox-exec-portrait').forEach(function(img) {
  if (!img.complete || img.naturalWidth === 0) {
    img.src = window.__PORTRAIT_FALLBACK;
  }
});